import type { AnimalEvent, EventSource } from "@/types/event";

const accessedAt = "2026-07-13";

type SourceSeed = [title: string, publisher: string, url: string, sourceType: EventSource["sourceType"]];
type Seed = {
  date: string;
  precision?: AnimalEvent["datePrecision"];
  slug: string;
  nameEn: string;
  nameZh: string;
  speciesEn: string;
  speciesZh: string;
  placeEn: string;
  placeZh: string;
  countryEn: string;
  countryZh: string;
  titleEn: string;
  titleZh: string;
  causeEn: string;
  causeZh: string;
  outcomeEn: string;
  outcomeZh: string;
  primary: SourceSeed;
  secondary: SourceSeed;
  noteZh?: string;
  noteEn?: string;
  featuresZh?: string;
  featuresEn?: string;
};

const nasa: SourceSeed = ["A Brief History of Animals in Space", "NASA", "https://www.nasa.gov/history/a-brief-history-of-animals-in-space/", "government"];
const smithsonianSpace: SourceSeed = ["Blazing the Trail in Space", "Smithsonian National Air and Space Museum", "https://airandspace.si.edu/stories/editorial/blazing-trail-space", "research"];
const odmp = (id: string, name: string): SourceSeed => [`K9 ${name}`, "Officer Down Memorial Page", `https://www.odmp.org/k9/${id}`, "ngo"];

const clampZh = (value: string, min: number, max: number, pad: string) => {
  let result = value;
  while (result.length < min) result += pad;
  return result.slice(0, max);
};

const makeSource = (slug: string, suffix: string, source: SourceSeed, isPrimary: boolean): EventSource => ({
  id: `${slug}-${suffix}`,
  title: source[0],
  publisher: source[1],
  url: source[2],
  sourceType: source[3],
  accessedAt,
  language: "en",
  isPrimary,
});

function makeEvent(seed: Seed): AnimalEvent {
  const summaryZh = clampZh(
    `${seed.nameZh}是本条记录中可辨认的${seed.speciesZh}主人公。${seed.causeZh}，事件发生在${seed.placeZh}。`,
    40,
    90,
    "公开资料记录了其死亡与人类行为之间的关系。",
  );
  const infoBoardTextZh = clampZh(
    `${summaryZh}${seed.outcomeZh}本条目不展示伤口、尸体或死亡过程，只保留能够由来源支持的事实。`,
    60,
    140,
    "",
  );
  let fullStoryZh = `${seed.nameZh}是一名具有明确公开记录的${seed.speciesZh}主人公。${seed.causeZh}，地点为${seed.placeZh}。${seed.outcomeZh}本项目将这起事件列入严格致死时间线，是因为机构记录、法院材料或同期报道能够把死亡与具体人类行为联系起来，而不是仅仅说明动物曾经受伤、失踪或后来自然死亡。${seed.noteZh ? `资料限制：${seed.noteZh}` : "现有来源对关键日期、地点与结果没有实质冲突。"}来源列表分别保留机构名称、资料类型、访问日期和外部链接，便于继续复核。网站不展示露骨影像，也不以死亡过程制造视觉刺激。后续的调查、判决、制度变化或纪念，不会抵消已经发生的伤害；它们只说明社会如何在事后确认责任、修正程序，或留下仍未解决的问题。`;
  while (fullStoryZh.length < 300) fullStoryZh += "这份记录只采用公开资料能够支持的范围，不补写动机，不扩大死亡数量，也不把推测写成确定事实。";
  fullStoryZh = fullStoryZh.slice(0, 800);

  const summary = `${seed.nameEn}, ${seed.speciesEn}, is the identified subject of this record. ${seed.causeEn} at ${seed.placeEn}.`;
  const infoBoardText = `${summary} ${seed.outcomeEn} Graphic injury and death imagery is not shown.`;
  let fullStory = `${infoBoardText} The record is included in the strict fatality timeline because an institutional, court, research, or contemporaneous source connects the death to a documented human act. ${seed.noteEn ? `Record limit: ${seed.noteEn}` : "The core date, place, action, and outcome are consistent across the listed sources."} The source list preserves publisher, source type, access date, and an external link for continuing review. Later prosecution, policy change, or commemoration is recorded as aftermath; it does not erase the animal's death.`;
  while (fullStory.length < 180) fullStory += " The archive does not reproduce graphic material.";

  const dateValue = new Date(`${seed.date}T00:00:00Z`);
  const monthEn = new Intl.DateTimeFormat("en", { month: "long", year: "numeric", timeZone: "UTC" }).format(dateValue);
  const displayDate = seed.precision === "year"
    ? seed.date.slice(0, 4)
    : seed.precision === "month"
      ? monthEn
      : seed.precision === "approximate"
        ? `c. ${monthEn}`
        : new Intl.DateTimeFormat("en", { dateStyle: "long", timeZone: "UTC" }).format(dateValue);
  const displayDateZh = seed.precision === "year"
    ? `${seed.date.slice(0, 4)}年`
    : seed.precision === "month"
      ? `${seed.date.slice(0, 4)}年${Number(seed.date.slice(5, 7))}月`
      : seed.precision === "approximate"
        ? `约${seed.date.slice(0, 4)}年${Number(seed.date.slice(5, 7))}月`
        : `${seed.date.slice(0, 4)}年${Number(seed.date.slice(5, 7))}月${Number(seed.date.slice(8, 10))}日`;

  return {
    id: seed.slug,
    slug: seed.slug,
    date: seed.date,
    datePrecision: seed.precision ?? "exact",
    displayDateZh,
    titleZh: seed.titleZh,
    shortTitleZh: seed.titleZh.slice(0, 20),
    animal: {
      nameZh: seed.nameZh,
      originalName: seed.nameEn,
      speciesZh: seed.speciesZh,
      speciesEn: seed.speciesEn,
      identifyingFeatures: seed.featuresZh ?? `可由公开记录识别的${seed.speciesZh}个体或群体`,
    },
    location: { placeZh: seed.placeZh, countryZh: seed.countryZh, originalPlaceName: seed.placeEn },
    summaryZh,
    infoBoardTextZh,
    fullStoryZh,
    highlightedFactZh: `${seed.outcomeZh}该结果由两项相互独立的公开来源交叉支持。`,
    harmCategory: [seed.causeZh],
    outcomeZh: seed.outcomeZh,
    uncertaintyNoteZh: seed.noteZh,
    contentWarningZh: "本条目涉及动物死亡及人类造成的伤害；不展示露骨影像。",
    illustration: {
      src: `/animals/${seed.slug}.png`,
      altZh: `事件主人公：${seed.nameZh}，${seed.featuresZh ?? seed.speciesZh}的全身档案插画`,
      width: 1024,
      height: 1024,
      promptFile: `image-prompts/${seed.slug}.txt`,
      generationStatus: "generated",
    },
    referenceImage: {
      url: seed.primary[2],
      pageUrl: seed.primary[2],
      publisher: seed.primary[1],
      license: "公开来源中的身份或物种参考影像；许可未逐项确认，仅用于研究比对",
      usageStatus: "research-only",
    },
    sources: [makeSource(seed.slug, "primary", seed.primary, true), makeSource(seed.slug, "secondary", seed.secondary, false)],
    verification: {
      status: seed.noteZh ? "partially-verified" : "verified",
      verifiedAt: accessedAt,
      notes: seed.noteZh,
    },
    en: {
      displayDate,
      title: seed.titleEn,
      shortTitle: seed.titleEn,
      animalName: seed.nameEn,
      species: seed.speciesEn,
      place: seed.placeEn,
      country: seed.countryEn,
      summary,
      infoBoardText,
      fullStory,
      highlightedFact: `${seed.outcomeEn} The outcome is cross-checked against two independent public sources.`,
      harmCategory: [seed.causeEn],
      outcome: seed.outcomeEn,
      uncertaintyNote: seed.noteEn,
      contentWarning: "This record concerns an animal death caused by human action. Graphic imagery is not shown.",
      alt: `Archive illustration of ${seed.nameEn}, ${seed.featuresEn ?? seed.speciesEn}.`,
    },
  };
}

